import { createReducer, on } from '@ngrx/store';
import { loadUsersSuccess, addUser, deleteUser } from './user.actions';

// Define the state shape
export interface UserState {
  users: User[];
  loading: boolean;
  error: string | null;
}

// Initial state
const initialState: UserState = {
  users: [],
  loading: false,
  error: null
};

// Reducer — pure function, returns NEW state
export const userReducer = createReducer(
  initialState,

  on(loadUsersSuccess, (state, { users }) => ({
    ...state,           // Copy existing state
    users: users,       // Update users array
    loading: false      // Set loading to false
  })),

  on(addUser, (state, { user }) => ({
    ...state,
    users: [...state.users, user]  // Add new user (immutable)
  })),

  on(deleteUser, (state, { userId }) => ({
    ...state,
    users: state.users.filter(u => u.id !== userId)  // Remove user
  }))
);

