// Auth interceptor (Angular 17 functional style)
import { HttpInterceptorFn, HttpErrorResponse } from '@angular/common/http';
import { inject } from '@angular/core';
import { Router } from '@angular/router';
import { catchError, throwError } from 'rxjs';

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const router = inject(Router);
  const token = localStorage.getItem('auth_token');

  // Clone request and add auth header
  let authReq = req;
  if (token) {
    authReq = req.clone({
      setHeaders: {
        Authorization: `Bearer ${token}`
      }
    });
  }

  return next(authReq).pipe(
    catchError((error: HttpErrorResponse) => {
      if (error.status === 401) {
        // Token expired or invalid — redirect to login
        localStorage.removeItem('auth_token');
        router.navigate(['/login']);
      }
      return throwError(() => error);
    })
  );
};

// Register in app.config.ts
import { provideHttpClient, withInterceptors } from '@angular/common/http';

export const appConfig: ApplicationConfig = {
  providers: [
    provideHttpClient(withInterceptors([authInterceptor]))
  ]
};

// Complete NgRx setup example

// 1. Define state
interface AppState {
  counter: number;
}

const initialState: AppState = { counter: 0 };

// 2. Define actions
const increment = createAction('[Counter] Increment');
const decrement = createAction('[Counter] Decrement');
const reset = createAction('[Counter] Reset');
const setCounter = createAction('[Counter] Set', props<{ value: number }>());

// 3. Create reducer
const counterReducer = createReducer(
  initialState,
  on(increment, state => ({ ...state, counter: state.counter + 1 })),
  on(decrement, state => ({ ...state, counter: state.counter - 1 })),
  on(reset, state => ({ ...state, counter: 0 })),
  on(setCounter, (state, { value }) => ({ ...state, counter: value }))
);

// 4. Use in component
@Component({
  template: `
    <p>Count: {{ count$ | async }}</p>
    <button (click)="inc()">+1</button>
    <button (click)="dec()">-1</button>
  `
})
export class CounterComponent {
  count$ = inject(Store).select(state => state.counter);
  private store = inject(Store);

  inc() { this.store.dispatch(increment()); }
  dec() { this.store.dispatch(decrement()); }
}

import { Injectable } from '@angular/core';
import { Actions, createEffect, ofType } from '@ngrx/effects';
import { switchMap, map, catchError } from 'rxjs/operators';
import { of } from 'rxjs';

@Injectable()
export class UserEffects {
  // Effect: Load users from API
  loadUsers$ = createEffect(() =>
    this.actions$.pipe(
      ofType('[User] Load Users'),       // Listen for this action
      switchMap(() =>
        this.userService.getUsers().pipe(
          map(users => ({ type: '[User] Load Success', users })),
          catchError(error =>
            of({ type: '[User] Load Failure', error: error.message })
          )
        )
      )
    )
  );

  // Effect: Show notification (no dispatch)
  showSuccess$ = createEffect(() =>
    this.actions$.pipe(
      ofType('[User] Load Success'),
      map(() => {
        alert('Users loaded successfully!');
      })
    ),
    { dispatch: false }  // This effect doesn't dispatch another action
  );

  constructor(
    private actions$: Actions,
    private userService: UserService
  ) { }
}

