// 1. Simple Retry with exponential backoff
import { retry, retryWhen, delay, scan, tap } from 'rxjs/operators';

// Simple retry — 3 attempts with 1 second delay
this.http.get('/api/data').pipe(
  retry({ count: 3, delay: 1000 })
).subscribe();

// Exponential backoff retry
this.http.get('/api/data').pipe(
  retryWhen(errors =>
    errors.pipe(
      scan((retryCount, error) => {
        if (retryCount >= 3) throw error; // Give up after 3
        return retryCount + 1;
      }, 0),
      tap(count => console.log(`Retry attempt ${count}`)),
      delay(count => count * 2000)  // 2s, 4s, 6s
    )
  )
).subscribe();

// 2. Caching with shareReplay
@Injectable({ providedIn: 'root' })
export class ProductService {
  private productsCache$?: Observable<Product[]>;

  getProducts(): Observable<Product[]> {
    if (!this.productsCache$) {
      this.productsCache$ = this.http.get<Product[]>('/api/products').pipe(
        shareReplay({ bufferSize: 1, refCount: true })
      );
    }
    return this.productsCache$;
  }

  clearCache() {
    this.productsCache$ = undefined;
  }
}

// 3. HTTP Caching Interceptor
export const cachingInterceptor: HttpInterceptorFn = (req, next) => {
  const cache = inject(CacheService);

  // Only cache GET requests
  if (req.method !== 'GET') return next(req);

  const cached = cache.get(req.url);
  if (cached && !cache.isExpired(req.url)) {
    return of(cached);  // Return cached response
  }

  return next(req).pipe(
    tap(response => {
      if (response instanceof HttpResponse) {
        cache.set(req.url, response, 300000); // Cache for 5 min
      }
    })
  );
};

