CREATE PROCEDURE sp_GetUserOrders
    @UserId INT,
    @MinAmount DECIMAL(18,2) = 0  -- Default parameter
AS
BEGIN
    SELECT o.Id, o.OrderDate, o.Total, p.Name AS ProductName
    FROM Orders o
    INNER JOIN OrderItems oi ON o.Id = oi.OrderId
    INNER JOIN Products p ON oi.ProductId = p.Id
    WHERE o.UserId = @UserId AND o.Total >= @MinAmount
    ORDER BY o.OrderDate DESC;
END;

