CREATE TABLE Users (
    Id INT PRIMARY KEY IDENTITY,
    Email NVARCHAR(100) NOT NULL UNIQUE,
    PasswordHash NVARCHAR(255) NOT NULL
);

CREATE TABLE UserProfiles (
    Id INT PRIMARY KEY IDENTITY,
    UserId INT UNIQUE NOT NULL,         -- One-to-One (UNIQUE FK)
    FullName NVARCHAR(100),
    Phone NVARCHAR(15),
    Address NVARCHAR(500),
    FOREIGN KEY (UserId) REFERENCES Users(Id)
);

-- 2. One-to-Many: Customer → Orders
CREATE TABLE Customers (
    Id INT PRIMARY KEY IDENTITY,
    Name NVARCHAR(100) NOT NULL,
    Email NVARCHAR(100) NOT NULL
);

CREATE TABLE Orders (
    Id INT PRIMARY KEY IDENTITY,
    CustomerId INT NOT NULL,            -- FK to Customers
    OrderDate DATETIME DEFAULT GETDATE(),
    Total DECIMAL(18,2),
    FOREIGN KEY (CustomerId) REFERENCES Customers(Id)
);

-- 3. Many-to-Many: Students ↔ Courses (Junction Table)
CREATE TABLE Students (
    Id INT PRIMARY KEY IDENTITY,
    Name NVARCHAR(100)
);

CREATE TABLE Courses (
    Id INT PRIMARY KEY IDENTITY,
    Title NVARCHAR(200)
);

CREATE TABLE Enrollments (            -- Junction/Bridge table
    StudentId INT NOT NULL,
    CourseId INT NOT NULL,
    EnrolledDate DATETIME DEFAULT GETDATE(),
    Grade NVARCHAR(2),
    PRIMARY KEY (StudentId, CourseId), -- Composite PK
    FOREIGN KEY (StudentId) REFERENCES Students(Id),
    FOREIGN KEY (CourseId) REFERENCES Courses(Id)
);

