// Multiple async operations
[HttpGet("dashboard")]
public async Task<IActionResult> GetDashboard()
{
    // Sequential — one after another (slower)
    var users = await _db.Users.CountAsync();
    var orders = await _db.Orders.CountAsync();
    var revenue = await _db.Orders.SumAsync(o => o.Total);

    // Parallel — all at once (faster!)
    var usersTask = _db.Users.CountAsync();
    var ordersTask = _db.Orders.CountAsync();
    var revenueTask = _db.Orders.SumAsync(o => o.Total);

    await Task.WhenAll(usersTask, ordersTask, revenueTask);

    return Ok(new {
        TotalUsers = usersTask.Result,
        TotalOrders = ordersTask.Result,
        TotalRevenue = revenueTask.Result
    });
}

