// 1. EF Core — Implicit Transaction (automatic)
public async Task CreateOrderAsync(Order order)
{
    _db.Orders.Add(order);           // Tracked by EF
    _db.OrderItems.AddRange(order.Items); // Also tracked
    await _db.SaveChangesAsync();     // One transaction for all changes
    // If any fails, ALL changes are rolled back
}

// 2. Explicit Transaction (multiple SaveChanges)
public async Task TransferMoneyAsync(int fromId, int toId, decimal amount)
{
    using var transaction = await _db.Database.BeginTransactionAsync();
    try
    {
        // Step 1: Debit from source account
        var source = await _db.Accounts.FindAsync(fromId);
        if (source!.Balance < amount)
            throw new Exception("Insufficient balance");

        source.Balance -= amount;
        await _db.SaveChangesAsync();

        // Step 2: Credit to destination account
        var dest = await _db.Accounts.FindAsync(toId);
        dest!.Balance += amount;
        await _db.SaveChangesAsync();

        // Both succeeded — commit
        await transaction.CommitAsync();
    }
    catch
    {
        // Something failed — rollback everything
        await transaction.RollbackAsync();
        throw;
    }
}

// 3. SQL Transaction Isolation Levels
// ReadUncommitted — fastest, can read dirty data
// ReadCommitted — default, reads only committed data
// RepeatableRead — locks read rows, prevents non-repeatable reads
// Serializable — strictest, full isolation, slowest

using var transaction = await _db.Database
    .BeginTransactionAsync(IsolationLevel.RepeatableRead);

