// 3. Fire-and-Forget Job (runs once, immediately in background)
[HttpPost("place-order")]
public IActionResult PlaceOrder(OrderDto dto)
{
    var orderId = _orderService.Create(dto);

    // These run in background — user doesn't wait!
    BackgroundJob.Enqueue(() => _emailService.SendOrderConfirmation(orderId));
    BackgroundJob.Enqueue(() => _invoiceService.GenerateInvoice(orderId));
    BackgroundJob.Enqueue(() => _inventoryService.UpdateStock(dto.Items));

    return Ok(new { orderId, message = "Order placed!" });
}

// 4. Delayed Job (runs after specified time)
BackgroundJob.Schedule(
    () => _emailService.SendReviewReminder(orderId),
    TimeSpan.FromDays(7));  // Send after 7 days

// 5. Recurring Job (runs on a schedule)
RecurringJob.AddOrUpdate(
    "daily-report",
    () => _reportService.GenerateDailyReport(),
    Cron.Daily);  // Every day at midnight

RecurringJob.AddOrUpdate(
    "cleanup-expired",
    () => _cleanupService.RemoveExpiredTokens(),
    "0 */6 * * *");  // Every 6 hours (CRON expression)

// 6. Continuation (runs after another job completes)
var jobId = BackgroundJob.Enqueue(() => _orderService.Process(orderId));
BackgroundJob.ContinueJobWith(jobId,
    () => _notificationService.NotifyCustomer(orderId));

