using System.Threading.RateLimiting;

builder.Services.AddRateLimiter(options =>
{
    // Fixed Window: 100 requests per 1 minute
    options.AddFixedWindowLimiter("fixed", opt =>
    {
        opt.PermitLimit = 100;
        opt.Window = TimeSpan.FromMinutes(1);
        opt.QueueProcessingOrder = QueueProcessingOrder.OldestFirst;
        opt.QueueLimit = 10;  // Queue up to 10 excess requests
    });

    // Sliding Window: smoother distribution
    options.AddSlidingWindowLimiter("sliding", opt =>
    {
        opt.PermitLimit = 100;
        opt.Window = TimeSpan.FromMinutes(1);
        opt.SegmentsPerWindow = 4;  // 4 segments of 15 seconds
    });

    // Token Bucket: allows bursts
    options.AddTokenBucketLimiter("token", opt =>
    {
        opt.TokenLimit = 100;           // Max tokens
        opt.ReplenishmentPeriod = TimeSpan.FromSeconds(10);
        opt.TokensPerPeriod = 20;       // Add 20 tokens every 10 sec
    });

    // Custom response when rate limited
    options.OnRejected = async (context, ct) =>
    {
        context.HttpContext.Response.StatusCode = 429;
        await context.HttpContext.Response.WriteAsJsonAsync(new
        {
            error = "Too many requests. Please try again later.",
            retryAfter = "60 seconds"
        }, ct);
    };
});

var app = builder.Build();
app.UseRateLimiter();  // Add middleware

